package edu.ankara.audiometer.application;
import edu.ankara.audiometer.domain.fp.Result;import edu.ankara.audiometer.domain.model.TestState;import edu.ankara.audiometer.infrastructure.export.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public final class AudiogramExportService { private final CsvAudiogramExporter csv=new CsvAudiogramExporter(); private final JsonSessionExporter json=new JsonSessionExporter(); public Result<Path,String> exportCsv(TestState s,Path p){ try{Files.createDirectories(p.getParent()); Files.writeString(p,csv.export(s),StandardCharsets.UTF_8); return Result.ok(p);}catch(Exception e){return Result.err(e.getMessage());}} public Result<Path,String> exportJson(TestState s,Path p){ var data=json.export(s); if(!data.isOk()) return Result.err("JSON export failed"); try{Files.createDirectories(p.getParent()); Files.writeString(p,data.orElse("{}"),StandardCharsets.UTF_8); return Result.ok(p);}catch(Exception e){return Result.err(e.getMessage());}} public String csvString(TestState s){return csv.export(s);} }
